      { prompt, image_size: "landscape_4_3", num_inference_steps: 4, num_images: 1, enable_safety_checker: true },
      req.signal,
    );
    return Response.json({ url, dataUri: await toDataUri(url, req.signal) });
  } catch (err) {
    return errorResponse(err);
  }
}
